# Identify variables with a positive correlation close to 0.00003018
threshold = 0.00003018
significant_vars = []

for col in correlation_matrix.columns:
    if col != 'HYBAS_ID' and col != 'long' and col != 'lat':
        for other_col in correlation_matrix.columns:
            if other_col != col and other_col != 'HYBAS_ID' and other_col != 'long' and other_col != 'lat':
